        "nadm.rotated": ["en": "Rotated — every record re-sealed under the new version.", "es": "Rotada: todos los registros se han vuelto a sellar con la nueva versión.", "fr": "Rotation effectuée — tous les enregistrements ont été rescellés sous la nouvelle version.", "de": "Rotiert — jeder Datensatz wurde unter der neuen Version neu versiegelt.", "pt": "Rodada — todos os registos foram novamente selados sob a nova versão.", "it": "Ruotata — ogni record è stato risigillato con la nuova versione.", "ja": "ローテーションしました — すべてのレコードを新しいバージョンで再封印しました。", "zh": "已轮换 — 所有记录已在新版本下重新封存。", "hi": "घुमाई गई — हर रिकॉर्ड नए संस्करण के तहत पुनः सील किया गया।", "ar": "تم التدوير — أُعيد ختم كل سجل بالإصدار الجديد."],
        "nfb.msg.ph": ["en": "What's on your mind?", "es": "¿Qué te preocupa?", "fr": "Qu'avez-vous en tête ?", "de": "Was beschäftigt Sie?", "pt": "O que lhe vai na cabeça?", "it": "A cosa stai pensando?", "ja": "気になっていることは？", "zh": "你在想什么？", "hi": "आपके मन में क्या है?", "ar": "بماذا تفكر؟"],
