        "fb.thanks": ["en": "Thank you — sent.", "es": "Gracias, enviado.", "fr": "Merci — envoyé.", "de": "Danke — gesendet.", "pt": "Obrigado — enviado.", "it": "Grazie — inviato.", "ja": "ありがとうございます — 送信しました。", "zh": "谢谢 — 已发送。", "hi": "धन्यवाद — भेज दिया गया।", "ar": "شكرًا لك — تم الإرسال."],
        "nrec.key": ["en": "Key", "es": "Clave", "fr": "Clé", "de": "Schlüssel", "pt": "Chave", "it": "Chiave", "ja": "キー", "zh": "键名", "hi": "कुंजी", "ar": "المفتاح"],
