        "nrec.value": ["en": "Value", "es": "Valor", "fr": "Valeur", "de": "Wert", "pt": "Valor", "it": "Valore", "ja": "値", "zh": "值", "hi": "मान", "ar": "القيمة"],
        "nrec.value.ph": ["en": "plaintext to seal", "es": "texto a sellar", "fr": "texte en clair à sceller", "de": "zu versiegelnder Klartext", "pt": "texto a selar", "it": "testo in chiaro da sigillare", "ja": "封印する平文", "zh": "要封存的明文", "hi": "सील करने हेतु सादा पाठ", "ar": "نص للختم"],
        "nrec.seal": ["en": "Seal record", "es": "Sellar el registro", "fr": "Sceller l'enregistrement", "de": "Datensatz versiegeln", "pt": "Selar o registo", "it": "Sigilla il record", "ja": "レコードを封印", "zh": "封存记录", "hi": "रिकॉर्ड सील करें", "ar": "ختم السجل"],
        "nrob.bind.go": ["en": "Bind", "es": "Vincular", "fr": "Associer", "de": "Verbinden", "pt": "Vincular", "it": "Collega", "ja": "接続", "zh": "绑定", "hi": "जोड़ें", "ar": "ربط"],
        "nacc.handle": ["en": "Handle (optional)", "es": "Identificador (opcional)", "fr": "Identifiant (facultatif)", "de": "Kennung (optional)", "pt": "Identificador (opcional)", "it": "Handle (facoltativo)", "ja": "ハンドル（任意）", "zh": "用户名（可选）", "hi": "हैंडल (वैकल्पिक)", "ar": "المعرّف (اختياري)"],
        "nacc.id.ph": ["en": "pdi_…", "es": "pdi_…", "fr": "pdi_…", "de": "pdi_…", "pt": "pdi_…", "it": "pdi_…", "ja": "pdi_…", "zh": "pdi_…", "hi": "pdi_…", "ar": "pdi_…"],
        "prb.can": ["en": "This app can send a count of what failed — the operation and the HTTP status, the day, and how many times. Not what you typed, not who you are, not which profile. Nothing that identifies you or anyone else.", "es": "Esta aplicación puede enviar un recuento de lo que falló: la operación y el estado HTTP, el día y cuántas veces. No lo que escribiste, ni quién eres, ni qué inquilino. Nada que te identifique a ti ni a nadie.", "fr": "Cette application peut envoyer un décompte des échecs : l'opération et le statut HTTP, le jour et le nombre de fois. Pas ce que vous avez saisi, ni qui vous êtes, ni quel locataire. Rien qui vous identifie, ni personne d'autre.", "de": "Diese App kann eine Anzahl der Fehler senden — den Vorgang und den HTTP-Status, den Tag und wie oft. Nicht, was Sie eingegeben haben, nicht, wer Sie sind, nicht welcher Mandant. Nichts, was Sie oder jemand anderen identifiziert.", "pt": "Esta aplicação pode enviar uma contagem do que falhou — a operação e o estado HTTP, o dia e quantas vezes. Não o que escreveu, nem quem é, nem que inquilino. Nada que o identifique a si ou a outra pessoa.", "it": "Questa app può inviare un conteggio degli errori — l'operazione e lo stato HTTP, il giorno e quante volte. Non ciò che hai digitato, non chi sei, non quale tenant. Nulla che identifichi te o chiunque altro.", "ja": "このアプリは失敗の件数を送信できます — 操作と HTTP ステータス、日付、回数です。入力した内容、あなたが誰か、どのテナントかは送りません。あなたや他の誰かを特定するものは何もありません。", "zh": "此应用可以发送失败计数 — 操作与 HTTP 状态、日期以及次数。不包括你输入的内容、你是谁、或哪个租户。没有任何能识别你或他人的信息。", "hi": "यह ऐप विफलताओं की गिनती भेज सकता है — कार्रवाई और HTTP स्थिति, दिन, और कितनी बार। आपने क्या टाइप किया, आप कौन हैं, कौन-सा टेनेंट — कुछ नहीं। ऐसा कुछ भी नहीं जो आपकी या किसी और की पहचान करे।", "ar": "يمكن لهذا التطبيق إرسال عدد ما فشل — العملية وحالة HTTP واليوم وعدد المرات. لا ما كتبته، ولا من أنت، ولا أي مستأجر. لا شيء يعرّفك أو يعرّف أي شخص آخر."],
        "prb.show": ["en": "Show what would be sent", "es": "Ver qué se enviaría", "fr": "Voir ce qui serait envoyé", "de": "Anzeigen, was gesendet würde", "pt": "Ver o que seria enviado", "it": "Mostra cosa verrebbe inviato", "ja": "送信される内容を表示", "zh": "查看将要发送的内容", "hi": "देखें क्या भेजा जाएगा", "ar": "إظهار ما سيُرسَل"],
        "prb.hide": ["en": "Hide what would be sent", "es": "Ocultar qué se enviaría", "fr": "Masquer ce qui serait envoyé", "de": "Ausblenden, was gesendet würde", "pt": "Ocultar o que seria enviado", "it": "Nascondi cosa verrebbe inviato", "ja": "送信される内容を隠す", "zh": "隐藏将要发送的内容", "hi": "छिपाएँ क्या भेजा जाएगा", "ar": "إخفاء ما سيُرسَل"],
        "prb.nowhere": ["en": "This build reports nowhere. Failures are counted on this machine and never leave it.", "es": "Esta compilación no informa a ninguna parte. Los fallos se cuentan en este equipo y nunca salen de él.", "fr": "Cette version ne signale rien à personne. Les échecs sont comptés sur cette machine et n'en sortent jamais.", "de": "Dieser Build meldet nirgendwohin. Fehler werden auf diesem Gerät gezählt und verlassen es nie.", "pt": "Esta compilação não reporta a lado nenhum. As falhas são contadas nesta máquina e nunca saem dela.", "it": "Questa build non segnala da nessuna parte. Gli errori sono contati su questa macchina e non la lasciano mai.", "ja": "このビルドはどこにも報告しません。障害はこの端末で数えられ、外に出ることはありません。", "zh": "此版本不向任何地方报告。故障只在本机计数，绝不外传。", "hi": "यह बिल्ड कहीं रिपोर्ट नहीं करता। विफलताएँ इसी मशीन पर गिनी जाती हैं और कभी बाहर नहीं जातीं।", "ar": "لا يُبلّغ هذا الإصدار أي جهة. تُحصى الأعطال على هذا الجهاز ولا تغادره أبدًا."],
        "ncon.disconnect": ["en": "Disconnect", "es": "Desconectar", "fr": "Déconnecter", "de": "Trennen", "pt": "Desligar", "it": "Scollega", "ja": "接続解除", "zh": "断开", "hi": "अलग करें", "ar": "فصل"],
        "nrob.snap": ["en": "Snapshot", "es": "Instantánea", "fr": "Instantané", "de": "Momentaufnahme", "pt": "Instantâneo", "it": "Istantanea", "ja": "スナップショット", "zh": "快照", "hi": "स्नैपशॉट", "ar": "لقطة"],
        "nrec.hide": ["en": "Hide", "es": "Ocultar", "fr": "Masquer", "de": "Ausblenden", "pt": "Ocultar", "it": "Nascondi", "ja": "隠す", "zh": "隐藏", "hi": "छिपाएँ", "ar": "إخفاء"],
        "nfb.title": ["en": "Help us improve", "es": "Ayúdanos a mejorar", "fr": "Aidez-nous à nous améliorer", "de": "Hilf uns, besser zu werden", "pt": "Ajude-nos a melhorar", "it": "Aiutaci a migliorare", "ja": "改善に力を貸してください", "zh": "帮助我们做得更好", "hi": "हमें बेहतर बनाने में मदद कीजिए", "ar": "ساعدنا على التحسّن"],
        "nfb.yours": ["en": "Yours", "es": "Lo tuyo", "fr": "Les vôtres", "de": "Deine", "pt": "Os seus", "it": "I tuoi", "ja": "あなたの送信分", "zh": "你发送的", "hi": "आपके भेजे हुए", "ar": "ما أرسلته"],
        "prob.server": ["en": "What has reached the server", "es": "Lo que ha llegado al servidor", "fr": "Ce qui a atteint le serveur", "de": "Was den Server erreicht hat", "pt": "O que chegou ao servidor", "it": "Cosa è arrivato al server", "ja": "サーバーに届いたもの", "zh": "已到达服务器的内容", "hi": "सर्वर तक क्या पहुँचा", "ar": "ما وصل إلى الخادم"],
        "prob.key.ph": ["en": "the problems key, if this deployment set one", "es": "la clave de problemas, si esta instalación fijó una", "fr": "la clé des problèmes, si ce déploiement en a défini une", "de": "der Problems-Schlüssel, falls diese Installation einen gesetzt hat", "pt": "a chave de problemas, se esta instalação definiu uma", "it": "la chiave dei problemi, se questa installazione ne ha una", "ja": "この配備で設定されていれば、その「problems」キー", "zh": "如果此部署设置了问题密钥，请输入", "hi": "समस्याओं की कुंजी, अगर इस परिनियोजन ने कोई रखी है", "ar": "مفتاح المشاكل، إن كان هذا النشر قد عيّن واحدًا"],
        "prob.fetch": ["en": "Read the aggregate", "es": "Leer el agregado", "fr": "Lire l'agrégat", "de": "Das Aggregat lesen", "pt": "Ler o agregado", "it": "Leggi l'aggregato", "ja": "集計を読む", "zh": "读取汇总", "hi": "समग्र पढ़ें", "ar": "اقرأ المجمّع"],
        "prob.none": ["en": "Nothing has been reported to this server yet.", "es": "Aún no se ha informado nada a este servidor.", "fr": "Rien n'a encore été rapporté à ce serveur.", "de": "Diesem Server wurde noch nichts gemeldet.", "pt": "Ainda nada foi comunicado a este servidor.", "it": "A questo server non è ancora stato segnalato nulla.", "ja": "このサーバーにはまだ何も報告されていません。", "zh": "尚未有任何报告到达此服务器。", "hi": "इस सर्वर को अभी तक कुछ नहीं बताया गया।", "ar": "لم يُبلَّغ هذا الخادم بشيء بعد."],
        "prb.title": ["en": "When something breaks", "es": "Cuando algo falla", "fr": "Quand quelque chose casse", "de": "Wenn etwas kaputtgeht", "pt": "Quando algo falha", "it": "Quando qualcosa si rompe", "ja": "何かが壊れたとき", "zh": "出问题的时候", "hi": "जब कुछ टूटे", "ar": "حين يتعطّل شيء"],
        "prb.send": ["en": "Send counts", "es": "Enviar los recuentos", "fr": "Envoyer les décomptes", "de": "Zählungen senden", "pt": "Enviar as contagens", "it": "Invia i conteggi", "ja": "件数を送る", "zh": "发送计数", "hi": "गिनती भेजें", "ar": "أرسل الأعداد"],
        "prb.donot": ["en": "Do not send", "es": "No enviar", "fr": "Ne pas envoyer", "de": "Nicht senden", "pt": "Não enviar", "it": "Non inviare", "ja": "送らない", "zh": "不要发送", "hi": "मत भेजें", "ar": "لا ترسل"],
        "prb.toggle": ["en": "Send failure counts", "es": "Enviar recuentos de fallos", "fr": "Envoyer les décomptes d'échecs", "de": "Fehlerzählungen senden", "pt": "Enviar contagens de falhas", "it": "Invia i conteggi degli errori", "ja": "失敗の件数を送る", "zh": "发送失败计数", "hi": "विफलताओं की गिनती भेजें", "ar": "أرسل أعداد الإخفاقات"],
        "prb.owed.none": ["en": "Nothing is owed. Either nothing has failed, or everything that has was already reported.", "es": "No hay nada pendiente. O no ha fallado nada, o todo lo que falló ya se informó.", "fr": "Rien n'est dû. Soit rien n'a échoué, soit tout ce qui a échoué a déjà été signalé.", "de": "Es steht nichts aus. Entweder ist nichts fehlgeschlagen, oder alles Fehlgeschlagene wurde bereits gemeldet.", "pt": "Não há nada em dívida. Ou nada falhou, ou tudo o que falhou já foi reportado.", "it": "Non c'è nulla in sospeso. O non è fallito nulla, o tutto ciò che è fallito è già stato segnalato.", "ja": "送るべきものはありません。何も失敗していないか、失敗したものはすべて報告済みです。", "zh": "没有待发送的内容。要么什么都没失败，要么失败过的都已上报。", "hi": "कुछ भी बकाया नहीं है। या तो कुछ विफल नहीं हुआ, या जो हुआ वह पहले ही भेजा जा चुका है।", "ar": "لا شيء معلّق. إما أن شيئًا لم يخفق، وإما أن كل ما أخفق قد أُبلغ عنه سلفًا."],
        "nov.unlocked": ["en": "Vault unlocked", "es": "Bóveda desbloqueada", "fr": "Coffre déverrouillé", "de": "Tresor entsperrt", "pt": "Cofre desbloqueado", "it": "Cassaforte sbloccata", "ja": "保管庫を解錠しました", "zh": "保险库已解锁", "hi": "वॉल्ट अनलॉक है", "ar": "الخزنة مفتوحة"],
        "nov.title": ["en": "Your vault", "es": "Tu bóveda", "fr": "Votre coffre", "de": "Dein Tresor", "pt": "O seu cofre", "it": "La tua cassaforte", "ja": "あなたの保管庫", "zh": "你的保险库", "hi": "आपका वॉल्ट", "ar": "خزنتك"],
        "nov.sealed": ["en": "Records are sealed at rest; every access is hash-chained in the audit log.", "es": "Los registros están sellados en reposo; cada acceso queda encadenado por hash en el registro de auditoría.", "fr": "Les enregistrements sont scellés au repos ; chaque accès est chaîné par hachage dans le journal d'audit.", "de": "Datensätze sind im Ruhezustand versiegelt; jeder Zugriff wird im Audit-Log hash-verkettet.", "pt": "Os registos estão selados em repouso; cada acesso fica encadeado por hash no registo de auditoria.", "it": "I record sono sigillati a riposo; ogni accesso è concatenato con hash nel registro di audit.", "ja": "レコードは保存時に封印され、すべてのアクセスは監査ログにハッシュ連鎖で記録されます。", "zh": "记录在静态时被封存；每次访问都以哈希链记入审计日志。", "hi": "रिकॉर्ड विश्राम अवस्था में सील रहते हैं; हर पहुँच ऑडिट लॉग में हैश-श्रृंखला से दर्ज होती है।", "ar": "السجلات مختومة أثناء التخزين؛ وكل وصول يُسلسل بالتجزئة في سجل التدقيق."],
        "nov.token": ["en": "Token", "es": "Token", "fr": "Jeton", "de": "Token", "pt": "Token", "it": "Token", "ja": "トークン", "zh": "令牌", "hi": "टोकन", "ar": "الرمز"],
        "nov.notes": ["en": "PDI's explanatory notes arrive in this language; sealed data is untouched.", "es": "Las notas explicativas de PDI llegan en este idioma; los datos sellados no se tocan.", "fr": "Les notes explicatives de PDI arrivent dans cette langue ; les données scellées restent intactes.", "de": "Die erläuternden Hinweise von PDI kommen in dieser Sprache an; versiegelte Daten bleiben unberührt.", "pt": "As notas explicativas do PDI chegam neste idioma; os dados selados ficam intocados.", "it": "Le note esplicative di PDI arrivano in questa lingua; i dati sigillati restano intatti.", "ja": "PDI の説明ノートはこの言語で届きます。封印されたデータには触れません。", "zh": "PDI 的说明性注释将以此语言送达；封存数据不受影响。", "hi": "PDI के व्याख्यात्मक नोट इसी भाषा में आते हैं; सीलबंद डेटा अछूता रहता है।", "ar": "تصل ملاحظات PDI التوضيحية بهذه اللغة؛ وتبقى البيانات المختومة كما هي."],
        "nov.pretrans": ["en": "Pre-translate notes", "es": "Pretraducir las notas", "fr": "Prétraduire les notes", "de": "Hinweise vorübersetzen", "pt": "Pré-traduzir as notas", "it": "Pre-traduci le note", "ja": "ノートを事前翻訳", "zh": "预翻译注释", "hi": "नोट पहले से अनुवाद करें", "ar": "ترجمة الملاحظات مسبقًا"],
        "nov.pretrans.off": ["en": "Off keeps English notes; sealed data is never touched either way.", "es": "Desactivado mantiene las notas en inglés; los datos sellados nunca se tocan en ningún caso.", "fr": "Désactivé garde les notes en anglais ; les données scellées ne sont jamais touchées, dans un cas comme dans l'autre.", "de": "Aus behält englische Hinweise; versiegelte Daten werden so oder so nie angerührt.", "pt": "Desligado mantém as notas em inglês; os dados selados nunca são tocados em nenhum dos casos.", "it": "Disattivato mantiene le note in inglese; i dati sigillati non vengono mai toccati in ogni caso.", "ja": "オフでは英語のノートのままです。いずれの場合も封印データには触れません。", "zh": "关闭则保留英文注释；无论开关，封存数据都不会被触碰。", "hi": "बंद रखने पर नोट अंग्रेज़ी में रहते हैं; दोनों ही स्थितियों में सीलबंद डेटा कभी नहीं छुआ जाता।", "ar": "الإيقاف يُبقي الملاحظات بالإنجليزية؛ ولا تُمسّ البيانات المختومة في الحالتين."],
        "nov.intact": ["en": "Intact", "es": "Íntegra", "fr": "Intacte", "de": "Intakt", "pt": "Íntegra", "it": "Integra", "ja": "正常", "zh": "完整", "hi": "अक्षुण्ण", "ar": "سليمة"],
        "nov.broken": ["en": "Broken", "es": "Rota", "fr": "Rompue", "de": "Gebrochen", "pt": "Quebrada", "it": "Rotta", "ja": "破損", "zh": "已断裂", "hi": "टूटी हुई", "ar": "مكسورة"],
        "nadm.title": ["en": "Admin · Key management", "es": "Administración · Gestión de claves", "fr": "Admin · Gestion des clés", "de": "Admin · Schlüsselverwaltung", "pt": "Admin · Gestão de chaves", "it": "Admin · Gestione delle chiavi", "ja": "管理 · 鍵の管理", "zh": "管理 · 密钥管理", "hi": "एडमिन · कुंजी प्रबंधन", "ar": "الإدارة · إدارة المفاتيح"],
        "nadm.req": ["en": "Requires the deployment's admin token (PDI_ADMIN_TOKEN) — not the tenant token. Kept in memory only, never stored.", "es": "Requiere el token de administrador del despliegue (PDI_ADMIN_TOKEN), no el token del inquilino. Se guarda solo en memoria, nunca se almacena.", "fr": "Nécessite le jeton d'administration du déploiement (PDI_ADMIN_TOKEN) — pas le jeton du locataire. Gardé en mémoire seulement, jamais stocké.", "de": "Erfordert das Admin-Token der Installation (PDI_ADMIN_TOKEN) — nicht das Mandanten-Token. Nur im Speicher gehalten, nie gespeichert.", "pt": "Requer o token de administrador da instalação (PDI_ADMIN_TOKEN) — não o token do inquilino. Mantido apenas em memória, nunca guardado.", "it": "Richiede il token di amministrazione dell'installazione (PDI_ADMIN_TOKEN), non il token del tenant. Tenuto solo in memoria, mai salvato.", "ja": "この環境の管理者トークン（PDI_ADMIN_TOKEN）が必要です — テナントのトークンではありません。メモリ内にのみ保持され、保存されることはありません。", "zh": "需要此部署的管理员令牌（PDI_ADMIN_TOKEN）——不是租户令牌。仅保存在内存中，绝不落盘。", "hi": "परिनियोजन का एडमिन टोकन (PDI_ADMIN_TOKEN) चाहिए — टेनेंट टोकन नहीं। केवल मेमोरी में रहता है, कभी संग्रहीत नहीं होता।", "ar": "يتطلب رمز المشرف الخاص بالنشر (PDI_ADMIN_TOKEN) — لا رمز المستأجر. يُحفظ في الذاكرة فقط ولا يُخزَّن أبدًا."],
        "nadm.dsr": ["en": "What do you hold about us", "es": "Qué guardáis sobre nosotros", "fr": "Que détenez-vous sur nous", "de": "Was haltet ihr über uns", "pt": "O que guardam sobre nós", "it": "Cosa conservate su di noi", "ja": "私たちについて何を保持していますか", "zh": "你们保存了我们的什么", "hi": "आप हमारे बारे में क्या रखते हैं", "ar": "ماذا تحتفظون عنا"],
        "naud.desc": ["en": "Every vault action is hash-chained. Verify recomputes the whole chain.", "es": "Cada acción de la bóveda se encadena por hash. Verificar recalcula toda la cadena.", "fr": "Chaque action du coffre est chaînée par hachage. Vérifier recalcule toute la chaîne.", "de": "Jede Tresor-Aktion wird hash-verkettet. Die Prüfung berechnet die gesamte Kette neu.", "pt": "Cada ação do cofre é encadeada por hash. Verificar recalcula toda a cadeia.", "it": "Ogni azione della cassaforte è concatenata con hash. La verifica ricalcola l'intera catena.", "ja": "保管庫のすべての操作はハッシュ連鎖されます。検証は連鎖全体を再計算します。", "zh": "保险库的每次操作都以哈希连成链。验证会重算整条链。", "hi": "वॉल्ट की हर कार्रवाई हैश-श्रृंखला में जुड़ती है। सत्यापन पूरी श्रृंखला की पुनर्गणना करता है।", "ar": "كل إجراء في الخزنة يُسلسل بالتجزئة. والتحقق يعيد حساب السلسلة كاملة."],
        "naud.verifying": ["en": "Verifying…", "es": "Verificando…", "fr": "Vérification…", "de": "Prüfung läuft…", "pt": "A verificar…", "it": "Verifica in corso…", "ja": "検証中…", "zh": "正在验证…", "hi": "सत्यापन हो रहा है…", "ar": "جارٍ التحقق…"],
        "naud.intact": ["en": "Chain intact", "es": "Cadena íntegra", "fr": "Chaîne intacte", "de": "Kette intakt", "pt": "Cadeia íntegra", "it": "Catena integra", "ja": "チェーンは正常です", "zh": "链条完整", "hi": "श्रृंखला अक्षुण्ण", "ar": "السلسلة سليمة"],
        "naud.broken": ["en": "Chain broken", "es": "Cadena rota", "fr": "Chaîne rompue", "de": "Kette gebrochen", "pt": "Cadeia quebrada", "it": "Catena rotta", "ja": "チェーンが破損しています", "zh": "链条已断裂", "hi": "श्रृंखला टूटी हुई", "ar": "السلسلة مكسورة"],
        "naud.events": ["en": "{n} recorded events", "es": "{n} eventos registrados", "fr": "{n} événements enregistrés", "de": "{n} erfasste Ereignisse", "pt": "{n} eventos registados", "it": "{n} eventi registrati", "ja": "記録済みイベント {n} 件", "zh": "已记录 {n} 个事件", "hi": "{n} दर्ज घटनाएँ", "ar": "{n} أحداث مسجلة"],
        "nfb.sub": ["en": "Tell us how to make PDI better — an idea, a rough edge, a bug, or what you love. It goes straight to the team.", "es": "Cuéntanos cómo mejorar PDI: una idea, algo áspero, un error o lo que te encanta. Va directo al equipo.", "fr": "Dites-nous comment améliorer PDI — une idée, un point rugueux, un bogue ou ce que vous aimez. Cela va droit à l'équipe.", "de": "Sag uns, wie PDI besser werden kann — eine Idee, eine raue Kante, ein Fehler oder was dir gefällt. Es geht direkt ans Team.", "pt": "Diga-nos como tornar o PDI melhor — uma ideia, uma aresta, um erro ou o que adora. Vai direto para a equipa.", "it": "Dicci come migliorare PDI — un'idea, uno spigolo, un bug o ciò che ami. Arriva dritto al team.", "ja": "PDI をより良くする方法を教えてください — アイデア、粗い部分、バグ、気に入っている点。そのままチームに届きます。", "zh": "告诉我们如何让 PDI 更好 — 一个想法、一处粗糙、一个错误，或你喜欢的地方。直达团队。", "hi": "बताइए PDI को बेहतर कैसे बनाएँ — कोई विचार, खुरदुरा किनारा, बग, या जो आपको पसंद है। सीधे टीम तक जाता है।", "ar": "أخبرنا كيف نجعل PDI أفضل — فكرة أو جانب خشن أو خلل أو ما تحبه. يصل مباشرة إلى الفريق."],
        "nfb.rating": ["en": "Rating", "es": "Valoración", "fr": "Note", "de": "Bewertung", "pt": "Classificação", "it": "Valutazione", "ja": "評価", "zh": "评分", "hi": "रेटिंग", "ar": "التقييم"],
        "nrec.sub": ["en": "Store a value — it is sealed at rest with AES-256-GCM.", "es": "Guarda un valor: se sella en reposo con AES-256-GCM.", "fr": "Stockez une valeur — elle est scellée au repos avec AES-256-GCM.", "de": "Speichere einen Wert — er wird im Ruhezustand mit AES-256-GCM versiegelt.", "pt": "Guarde um valor — é selado em repouso com AES-256-GCM.", "it": "Conserva un valore — è sigillato a riposo con AES-256-GCM.", "ja": "値を保存します — 保存時に AES-256-GCM で封印されます。", "zh": "存入一个值 — 静态时以 AES-256-GCM 封存。", "hi": "कोई मान रखें — विश्राम अवस्था में AES-256-GCM से सील होता है।", "ar": "خزّن قيمة — تُختم أثناء التخزين بـ AES-256-GCM."],
        "nrec.none": ["en": "No records yet — seal one above.", "es": "Aún no hay registros: sella uno arriba.", "fr": "Pas encore d'enregistrements — scellez-en un ci-dessus.", "de": "Noch keine Datensätze — versiegle oben einen.", "pt": "Ainda não há registos — sele um acima.", "it": "Ancora nessun record — sigillane uno qui sopra.", "ja": "まだレコードがありません — 上で封印してください。", "zh": "还没有记录 — 在上方封存一条。", "hi": "अभी कोई रिकॉर्ड नहीं — ऊपर एक सील करें।", "ar": "لا سجلات بعد — اختم واحدًا أعلاه."],
        "nrec.reveal": ["en": "Reveal", "es": "Revelar", "fr": "Révéler", "de": "Aufdecken", "pt": "Revelar", "it": "Rivela", "ja": "表示", "zh": "显示", "hi": "दिखाएँ", "ar": "كشف"],
        "nrec.prov": ["en": "Provenance", "es": "Procedencia", "fr": "Provenance", "de": "Herkunft", "pt": "Proveniência", "it": "Provenienza", "ja": "来歴", "zh": "来源", "hi": "उद्गम", "ar": "المصدر"],
        "nrec.origin": ["en": "Origin: {x}", "es": "Origen: {x}", "fr": "Origine : {x}", "de": "Ursprung: {x}", "pt": "Origem: {x}", "it": "Origine: {x}", "ja": "由来：{x}", "zh": "来源：{x}", "hi": "उद्गम: {x}", "ar": "الأصل: {x}"],
        "nrec.sealedline": ["en": "Sealed {date} · {n} ciphertext bytes", "es": "Sellado {date} · {n} bytes de texto cifrado", "fr": "Scellé {date} · {n} octets chiffrés", "de": "Versiegelt {date} · {n} Chiffrat-Bytes", "pt": "Selado {date} · {n} bytes cifrados", "it": "Sigillato {date} · {n} byte cifrati", "ja": "封印 {date} · 暗号文 {n} バイト", "zh": "封存于 {date} · 密文 {n} 字节", "hi": "सील {date} · {n} सिफरटेक्स्ट बाइट", "ar": "خُتم {date} · {n} بايت مشفّر"],
        "nrec.auditline": ["en": "{n} audit event(s) · chain {status}", "es": "{n} evento(s) de auditoría · cadena {status}", "fr": "{n} événement(s) d'audit · chaîne {status}", "de": "{n} Audit-Ereignis(se) · Kette {status}", "pt": "{n} evento(s) de auditoria · cadeia {status}", "it": "{n} evento/i di audit · catena {status}", "ja": "監査イベント {n} 件 · チェーン {status}", "zh": "{n} 个审计事件 · 链 {status}", "hi": "{n} ऑडिट घटनाएँ · श्रृंखला {status}", "ar": "{n} أحداث تدقيق · السلسلة {status}"],
        "nrec.chain.ok": ["en": "intact ✓", "es": "íntegra ✓", "fr": "intacte ✓", "de": "intakt ✓", "pt": "íntegra ✓", "it": "integra ✓", "ja": "正常 ✓", "zh": "完整 ✓", "hi": "अक्षुण्ण ✓", "ar": "سليمة ✓"],
        "nrec.chain.bad": ["en": "BROKEN", "es": "ROTA", "fr": "ROMPUE", "de": "GEBROCHEN", "pt": "QUEBRADA", "it": "ROTTA", "ja": "破損", "zh": "已断裂", "hi": "टूटी", "ar": "مكسورة"],
        "nrob.sub": ["en": "What your robots see stays sealed — every intake is encrypted at rest and hash-chained in the audit log.", "es": "Lo que ven tus robots queda sellado: cada entrada se cifra en reposo y se encadena por hash en el registro de auditoría.", "fr": "Ce que voient vos robots reste scellé — chaque entrée est chiffrée au repos et chaînée par hachage dans le journal d'audit.", "de": "Was deine Roboter sehen, bleibt versiegelt — jede Aufnahme wird im Ruhezustand verschlüsselt und im Audit-Log hash-verkettet.", "pt": "O que os seus robôs veem fica selado — cada entrada é cifrada em repouso e encadeada por hash no registo de auditoria.", "it": "Ciò che vedono i tuoi robot resta sigillato — ogni acquisizione è cifrata a riposo e concatenata con hash nel registro di audit.", "ja": "ロボットが見たものは封印されたままです — すべての取り込みは保存時に暗号化され、監査ログにハッシュ連鎖で記録されます。", "zh": "你的机器人所见都被封存 — 每次采集都在静态加密，并以哈希链记入审计日志。", "hi": "आपके रोबोट जो देखते हैं वह सील रहता है — हर इनटेक विश्राम में एन्क्रिप्ट होता है और ऑडिट लॉग में हैश-श्रृंखला से जुड़ता है।", "ar": "ما تراه روبوتاتك يبقى مختومًا — كل التقاط يُشفَّر أثناء التخزين ويُسلسل بالتجزئة في سجل التدقيق."],
        "nrob.bind": ["en": "Bind a robot", "es": "Vincular un robot", "fr": "Associer un robot", "de": "Einen Roboter verbinden", "pt": "Vincular um robô", "it": "Collega un robot", "ja": "ロボットを接続", "zh": "绑定一台机器人", "hi": "एक रोबोट जोड़ें", "ar": "اربط روبوتًا"],
        "nrob.sealed": ["en": "Sealed", "es": "Sellado", "fr": "Scellé", "de": "Versiegelt", "pt": "Selado", "it": "Sigillato", "ja": "封印済み", "zh": "已封存", "hi": "सील हो गया", "ar": "مختوم"],
        "nrob.count": ["en": "{n} sealed", "es": "{n} sellados", "fr": "{n} scellés", "de": "{n} versiegelt", "pt": "{n} selados", "it": "{n} sigillati", "ja": "封印済み {n} 件", "zh": "已封存 {n} 项", "hi": "{n} सील किए गए", "ar": "{n} مختومة"],
        "nrob.read": ["en": "Read it (audited) via Vault → the key above.", "es": "Léelo (auditado) en Bóveda → la clave de arriba.", "fr": "Lisez-le (audité) via Coffre → la clé ci-dessus.", "de": "Lies es (auditiert) über Tresor → den Schlüssel oben.", "pt": "Leia-o (auditado) em Cofre → a chave acima.", "it": "Leggilo (con audit) da Cassaforte → la chiave qui sopra.", "ja": "保管庫 → 上のキーから（監査付きで）読めます。", "zh": "经保险库 → 上方键名读取（有审计）。", "hi": "वॉल्ट → ऊपर की कुंजी से (ऑडिट सहित) पढ़ें।", "ar": "اقرأه (بتدقيق) عبر الخزنة → المفتاح أعلاه."],
        "nrob.map": ["en": "Seal map", "es": "Sellar el mapa", "fr": "Sceller la carte", "de": "Karte versiegeln", "pt": "Selar o mapa", "it": "Sigilla la mappa", "ja": "地図を封印", "zh": "封存地图", "hi": "नक्शा सील करें", "ar": "ختم الخريطة"],
        "nrob.log": ["en": "Sensor log", "es": "Registro de sensores", "fr": "Journal des capteurs", "de": "Sensorprotokoll", "pt": "Registo de sensores", "it": "Registro dei sensori", "ja": "センサーログ", "zh": "传感器日志", "hi": "सेंसर लॉग", "ar": "سجل المستشعرات"],
        "ncon.sub": ["en": "Link a platform account. Collected content is sealed into the vault; every ingest is hash-chained in the audit log.", "es": "Vincula una cuenta de plataforma. El contenido recogido se sella en la bóveda; cada ingesta se encadena por hash en el registro de auditoría.", "fr": "Associez un compte de plateforme. Le contenu collecté est scellé dans le coffre ; chaque ingestion est chaînée par hachage dans le journal d'audit.", "de": "Verknüpfe ein Plattform-Konto. Gesammelte Inhalte werden im Tresor versiegelt; jede Aufnahme wird im Audit-Log hash-verkettet.", "pt": "Vincule uma conta de plataforma. O conteúdo recolhido é selado no cofre; cada ingestão fica encadeada por hash no registo de auditoria.", "it": "Collega un account di piattaforma. I contenuti raccolti sono sigillati nella cassaforte; ogni acquisizione è concatenata con hash nel registro di audit.", "ja": "プラットフォームのアカウントを連携します。収集されたコンテンツは保管庫に封印され、すべての取り込みは監査ログにハッシュ連鎖で記録されます。", "zh": "关联一个平台账户。采集的内容封存进保险库；每次摄取都以哈希链记入审计日志。", "hi": "कोई प्लेटफ़ॉर्म खाता जोड़ें। एकत्र सामग्री वॉल्ट में सील होती है; हर इनजेस्ट ऑडिट लॉग में हैश-श्रृंखला से जुड़ता है।", "ar": "اربط حساب منصة. يُختم المحتوى المجموع في الخزنة؛ وكل إدخال يُسلسل بالتجزئة في سجل التدقيق."],
        "ncon.collect": ["en": "Connect to collect", "es": "Conectar para recoger", "fr": "Connecter pour collecter", "de": "Zum Sammeln verbinden", "pt": "Ligar para recolher", "it": "Connetti per raccogliere", "ja": "収集のために接続", "zh": "连接以采集", "hi": "एकत्र करने के लिए जोड़ें", "ar": "اتصال للجمع"],
        "ncon.publish": ["en": "Connect to publish", "es": "Conectar para publicar", "fr": "Connecter pour publier", "de": "Zum Veröffentlichen verbinden", "pt": "Ligar para publicar", "it": "Connetti per pubblicare", "ja": "公開のために接続", "zh": "连接以发布", "hi": "प्रकाशित करने के लिए जोड़ें", "ar": "اتصال للنشر"],
